export function UrlState({
  basePath = "{{basePath}}",
  tab = "{{tab}}",
  page = {{page}},
  accent = "{{accent}}",
}) {
  const tabs = ["results", "images", "news"];
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 320, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, background: "#ffffff", border: "1px solid #24143018", borderRadius: 8, padding: "8px 10px", marginBottom: 10 }}>
        <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#24143030", flexShrink: 0 }} />
        <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#24143030", flexShrink: 0 }} />
        <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#24143030", flexShrink: 0 }} />
        <code style={{ fontFamily: "ui-monospace, monospace", fontSize: 10, marginLeft: 4, wordBreak: "break-all" }}>yoursite.app{basePath}?tab={tab}&amp;page={page}</code>
      </div>
      <div style={{ display: "flex", gap: 6, marginBottom: 10 }}>
        {tabs.map((t) => (
          <span key={t} style={{ flex: 1, textAlign: "center", padding: "7px 4px", borderRadius: 6, fontSize: 11, fontWeight: 600, background: t === tab ? accent : "#24143010" }}>{t[0].toUpperCase() + t.slice(1)}</span>
        ))}
      </div>
      <p style={{ margin: 0, fontSize: 10, color: "#24143099" }}>Refreshing, sharing or bookmarking this link reproduces exactly this view &mdash; the state lives in the URL, not in memory.</p>
    </div>
  );
}
